"""
Everything that touches Terraform.

Design choices that keep the LLM's job small:
  * Field definitions come from `terraform providers schema -json`, the provider's own
    source of truth. No LLM-extracted schemas.
  * main.tf and variables.tf are generated by code. The model only supplies VALUES.
  * Scenarios are written as .tfvars.json, so the model can't produce HCL syntax errors.
  * Secrets reach Terraform through TF_VAR_* environment variables, never through files.
"""
from __future__ import annotations

import json
import os
import re
import subprocess
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable

from config import Settings

# (argv, cwd, env, timeout) -> (returncode, combined output)
Executor = Callable[[list[str], Path, dict[str, str], int], tuple[int, str]]

HARNESS_VARS = ("harness_host_url", "harness_username", "harness_password")
PLACEHOLDER_RE = re.compile(r"<[^>]+>|\b(todo|changeme|placeholder|replace_me)\b|\byour[_-]", re.I)


def subprocess_executor(argv: list[str], cwd: Path, env: dict[str, str], timeout: int) -> tuple[int, str]:
    try:
        p = subprocess.run(argv, cwd=cwd, env=env, capture_output=True, text=True, timeout=timeout)
        return p.returncode, p.stdout + p.stderr
    except subprocess.TimeoutExpired:
        return 124, f"Error: terraform timed out after {timeout}s"
    except FileNotFoundError:
        return 127, f"Error: '{argv[0]}' not found. Install Terraform or set TERRAFORM_BIN."


# ── Schema ───────────────────────────────────────────────────────────────────
@dataclass(frozen=True)
class FieldSpec:
    name: str
    tf_type: str    # type used in variables.tf
    kind: str       # "string" | "number" | "bool" | "complex"
    required: bool
    description: str
    sensitive: bool = False


def _map_type(t: Any) -> tuple[str, str]:
    if t == "string":
        return "string", "string"
    if t == "number":
        return "number", "number"
    if t == "bool":
        return "bool", "bool"
    return "any", "complex"  # lists, sets, maps, objects: the provider validates the shape


def parse_resource_fields(resource_schema: dict) -> list[FieldSpec]:
    """Settable attributes only. Computed-only attributes can't be set, so the model never sees them."""
    attrs = (resource_schema.get("block") or {}).get("attributes") or {}
    fields = []
    for name, a in sorted(attrs.items()):
        if name == "id" or not (a.get("required") or a.get("optional")):
            continue
        tf_type, kind = ("any", "complex") if "nested_type" in a else _map_type(a.get("type"))
        fields.append(FieldSpec(name, tf_type, kind, bool(a.get("required")),
                                " ".join((a.get("description") or "").split()), bool(a.get("sensitive"))))
    return fields


def nested_blocks(resource_schema: dict) -> list[str]:
    return sorted(((resource_schema.get("block") or {}).get("block_types") or {}).keys())


# ── File rendering (pure functions, easy to test) ─────────────────────────────
def render_provider_tf(source: str, version: str, with_provider_block: bool = True) -> str:
    version_line = f'\n      version = "{version}"' if version else ""
    tf = f'''terraform {{
  required_providers {{
    nios = {{
      source  = "{source}"{version_line}
    }}
  }}
}}
'''
    if with_provider_block:
        # Argument names follow the infobloxopen/nios provider docs; adjust if your version differs.
        tf += '''
variable "harness_host_url" { type = string }
variable "harness_username" { type = string }
variable "harness_password" {
  type      = string
  sensitive = true
}

provider "nios" {
  nios_host_url = var.harness_host_url
  nios_username = var.harness_username
  nios_password = var.harness_password
}
'''
    return tf


def render_variables_tf(fields: list[FieldSpec]) -> str:
    blocks = []
    for f in fields:
        sensitive = "\n  sensitive = true" if f.sensitive else ""
        # default = null means "not set": optional fields the scenario omits are simply absent.
        blocks.append(f'variable "{f.name}" {{\n  type    = {f.tf_type}\n  default = null{sensitive}\n}}\n')
    return "\n".join(blocks)


def render_main_tf(resource_type: str, fields: list[FieldSpec]) -> str:
    width = max((len(f.name) for f in fields), default=0)
    lines = [f"  {f.name.ljust(width)} = var.{f.name}" for f in fields]
    return f'resource "{resource_type}" "under_test" {{\n' + "\n".join(lines) + "\n}\n"


# ── Value checks (before Terraform ever runs) ─────────────────────────────────
def coerce_values(fields: list[FieldSpec], values: dict[str, Any]) -> dict[str, Any]:
    by_name = {f.name: f for f in fields}
    out = dict(values)
    for key, v in values.items():
        f = by_name.get(key)
        if not f or not isinstance(v, str):
            continue
        s = v.strip()
        if f.kind == "number" and re.fullmatch(r"-?\d+(\.\d+)?", s):
            out[key] = float(s) if "." in s else int(s)
        elif f.kind == "bool" and s.lower() in {"true", "false"}:
            out[key] = s.lower() == "true"
        elif f.kind == "complex" and s[:1] in "[{":
            try:
                out[key] = json.loads(s)
            except json.JSONDecodeError:
                pass
    return out


def validate_values(fields: list[FieldSpec], values: dict[str, Any]) -> list[str]:
    by_name = {f.name: f for f in fields}
    problems = []
    unknown = sorted(k for k in values if k not in by_name)
    if unknown:
        problems.append(f"unknown field(s) {unknown}. Valid fields: {sorted(by_name)}")
    for f in fields:
        v = values.get(f.name)
        if v is None:
            if f.required:
                problems.append(f"required field '{f.name}' is missing")
            continue
        if f.kind == "string" and not isinstance(v, str):
            problems.append(f"'{f.name}' must be a string, got {type(v).__name__}")
        elif f.kind == "number" and (isinstance(v, bool) or not isinstance(v, (int, float))):
            problems.append(f"'{f.name}' must be a number, got {v!r}")
        elif f.kind == "bool" and not isinstance(v, bool):
            problems.append(f"'{f.name}' must be true or false, got {v!r}")
        elif isinstance(v, str) and PLACEHOLDER_RE.search(v):
            problems.append(f"'{f.name}' looks like a placeholder ({v!r}); use a realistic value")
    return problems


# ── Output parsing ───────────────────────────────────────────────────────────
def extract_errors(output: str, limit: int = 5) -> list[str]:
    """Pull 'Error:' diagnostics out of Terraform output, dropping the box-drawing characters."""
    lines = [re.sub(r"^[│╷╵]\s?", "", line.rstrip()) for line in output.splitlines()]
    errors: list[str] = []
    current: list[str] | None = None
    for line in lines:
        if line.startswith("Error: "):
            if current:
                errors.append("\n".join(current).strip())
            current = [line]
        elif line.startswith("Warning: "):
            if current:
                errors.append("\n".join(current).strip())
            current = None
        elif current is not None:
            current.append(line)
    if current:
        errors.append("\n".join(current).strip())
    return errors[:limit]


def plan_summary(output: str) -> str:
    m = re.search(r"Plan: \d+ to add, \d+ to change, \d+ to destroy\.", output)
    if m:
        return m.group(0)
    return "No changes." if "No changes." in output else "Plan succeeded."


def _headline(error: str) -> str:
    """'Error: <summary>' plus the first line of the detail text. Terraform indents its
    context lines ('with ...', 'on main.tf line 4'), so the detail is the first unindented line."""
    lines = error.splitlines()
    summary = lines[0].removeprefix("Error: ").strip() if lines else "error"
    detail = next((l.strip() for l in lines[1:] if l.strip() and not l.startswith(" ")), "")
    return f"{summary}: {detail}" if detail else summary


@dataclass
class TfOutcome:
    ok: bool
    stage: str          # init | plan | apply | destroy | precheck
    summary: str
    errors: list[str]

    def for_model(self) -> str:
        if self.ok:
            return f"{self.stage.upper()} OK: {self.summary}"
        if not self.errors:
            return f"{self.stage.upper()} FAILED: {self.summary}"
        return f"{self.stage.upper()} FAILED: {_headline(self.errors[0])}\n\n" + "\n\n".join(self.errors)


# ── Runner ───────────────────────────────────────────────────────────────────
class TerraformRunner:
    def __init__(self, settings: Settings, executor: Executor = subprocess_executor):
        self.s = settings
        self.exec = executor
        self.root = settings.workspace / "terraform"
        self._schema: dict | None = None

    # Environment: secrets go in as TF_VAR_* so they never touch disk.
    def _env(self) -> dict[str, str]:
        return {**os.environ, "TF_IN_AUTOMATION": "1", "TF_INPUT": "0",
                "TF_VAR_harness_host_url": self.s.nios_host_url,
                "TF_VAR_harness_username": self.s.nios_username,
                "TF_VAR_harness_password": self.s.nios_password}

    def _tf(self, args: list[str], cwd: Path) -> tuple[int, str]:
        return self.exec([self.s.terraform_bin, *args], cwd, self._env(), self.s.terraform_timeout)

    # ── Provider schema ─────────────────────────────────────────────────────
    def schema(self, refresh: bool = False) -> dict:
        if self._schema is not None and not refresh:
            return self._schema
        d = self.root / "_schema"
        d.mkdir(parents=True, exist_ok=True)
        cache = d / "schema.json"
        if cache.exists() and not refresh:
            self._schema = json.loads(cache.read_text(encoding="utf-8"))
            return self._schema
        (d / "provider.tf").write_text(
            render_provider_tf(self.s.provider_source, self.s.provider_version, with_provider_block=False))
        rc, out = self._tf(["init", "-no-color"], d)
        if rc != 0:
            details = "\n".join(extract_errors(out)) or out[-2000:]
            raise RuntimeError(f"terraform init failed while loading the provider schema:\n{details}")
        rc, out = self._tf(["providers", "schema", "-json"], d)
        if rc != 0:
            raise RuntimeError(f"terraform providers schema failed:\n{out[-2000:]}")
        cache.write_text(out, encoding="utf-8")
        self._schema = json.loads(out)
        return self._schema

    def resource_types(self) -> list[str]:
        names: list[str] = []
        for provider in (self.schema().get("provider_schemas") or {}).values():
            names.extend((provider.get("resource_schemas") or {}).keys())
        return sorted(names)

    def resource_schema(self, resource_type: str) -> dict | None:
        for provider in (self.schema().get("provider_schemas") or {}).values():
            found = (provider.get("resource_schemas") or {}).get(resource_type)
            if found:
                return found
        return None

    def fields(self, resource_type: str) -> list[FieldSpec]:
        rs = self.resource_schema(resource_type)
        if rs is None:
            raise KeyError(resource_type)
        return parse_resource_fields(rs)

    # ── Working directory per resource ──────────────────────────────────────
    def resource_dir(self, resource_type: str) -> Path:
        return self.root / resource_type

    def scenario_path(self, resource_type: str, scenario: str) -> Path:
        return self.resource_dir(resource_type) / "scenarios" / f"{scenario}.tfvars.json"

    def prepare(self, resource_type: str) -> TfOutcome:
        """Generate .tf files from the schema and run init once. Safe to call repeatedly."""
        fields = self.fields(resource_type)
        d = self.resource_dir(resource_type)
        (d / "scenarios").mkdir(parents=True, exist_ok=True)
        files = {
            "provider.tf": render_provider_tf(self.s.provider_source, self.s.provider_version),
            "variables.tf": render_variables_tf(fields),
            "main.tf": render_main_tf(resource_type, fields),
        }
        for name, content in files.items():
            path = d / name
            if not path.exists() or path.read_text() != content:
                path.write_text(content)
        if not (d / ".terraform").exists():
            rc, out = self._tf(["init", "-no-color"], d)
            if rc != 0:
                return TfOutcome(False, "init", "terraform init failed", extract_errors(out) or [out[-2000:]])
        return TfOutcome(True, "init", "ready", [])

    # ── Commands ────────────────────────────────────────────────────────────
    def plan(self, resource_type: str, scenario: str) -> TfOutcome:
        ready = self.prepare(resource_type)
        if not ready.ok:
            return ready
        var_file = f"scenarios/{scenario}.tfvars.json"
        rc, out = self._tf(["plan", "-no-color", "-input=false", "-lock=false", f"-var-file={var_file}"],
                           self.resource_dir(resource_type))
        if rc != 0:
            return TfOutcome(False, "plan", "terraform plan failed", extract_errors(out) or [out[-2000:]])
        return TfOutcome(True, "plan", plan_summary(out), [])

    def state_resources(self, resource_type: str) -> list[str]:
        rc, out = self._tf(["state", "list"], self.resource_dir(resource_type))
        return [line for line in out.splitlines() if line.strip()] if rc == 0 else []

    def cleanup(self, resource_type: str, scenario: str) -> TfOutcome:
        """Destroy whatever is in state (used by the CLI after a failed destroy)."""
        rc, out = self._tf(["destroy", "-no-color", "-input=false", "-auto-approve",
                            f"-var-file=scenarios/{scenario}.tfvars.json"], self.resource_dir(resource_type))
        if rc != 0:
            return TfOutcome(False, "destroy", "cleanup failed", extract_errors(out) or [out[-2000:]])
        return TfOutcome(True, "destroy", "state is clean", [])

    def apply_and_destroy(self, resource_type: str, scenario: str) -> tuple[TfOutcome, TfOutcome | None]:
        """Create the object on NIOS, then always destroy it. Refuses to run on dirty state."""
        ready = self.prepare(resource_type)
        if not ready.ok:
            return ready, None
        d = self.resource_dir(resource_type)
        leftover = self.state_resources(resource_type)
        if leftover:
            return TfOutcome(False, "precheck", "state is not empty from an earlier run",
                             [f"Resources still in state: {leftover}. Run cleanup before applying."]), None
        var_file = f"-var-file=scenarios/{scenario}.tfvars.json"
        rc, out = self._tf(["apply", "-no-color", "-input=false", "-auto-approve", var_file], d)
        applied = (TfOutcome(True, "apply", "applied", []) if rc == 0 else
                   TfOutcome(False, "apply", "terraform apply failed", extract_errors(out) or [out[-2000:]]))
        # Destroy even when apply fails: a partial apply can still leave objects behind.
        rc, out = self._tf(["destroy", "-no-color", "-input=false", "-auto-approve", var_file], d)
        destroyed = (TfOutcome(True, "destroy", "destroyed", []) if rc == 0 else
                     TfOutcome(False, "destroy", "CLEANUP FAILED: objects may remain on NIOS",
                               extract_errors(out) or [out[-2000:]]))
        return applied, destroyed
